"""Self-contained C.O.R.T.E.X. operations dashboard."""
from __future__ import annotations


def get_ui_html() -> str:
    return r'''<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>C.O.R.T.E.X. Operations</title>
<style>
:root{--bg:#07111f;--panel:#0e1d31;--panel2:#12263d;--line:#23415e;--text:#e8f1fa;--muted:#8fa8bf;--cyan:#55d6f5;--green:#55e39a;--amber:#f6c85f;--red:#ff7185;--purple:#ac91ff;--shadow:0 18px 50px #0005}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -20%,#19405f 0,#07111f 45%);color:var(--text);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}button,input,select{font:inherit}button{cursor:pointer;border:1px solid #2f5878;border-radius:8px;background:#173452;color:var(--text);padding:9px 13px}button:hover{background:#204568;border-color:var(--cyan)}.shell{max-width:1480px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:24px}.brand{display:flex;gap:14px;align-items:center}.mark{width:46px;height:46px;border:1px solid var(--cyan);border-radius:14px;display:grid;place-items:center;color:var(--cyan);font-weight:800;font-size:18px;box-shadow:0 0 26px #55d6f533}.eyebrow{color:var(--cyan);font-size:11px;letter-spacing:.18em;text-transform:uppercase}.title{font-size:28px;font-weight:750;letter-spacing:-.03em;margin:2px 0}.subtitle{color:var(--muted)}.status{display:flex;align-items:center;gap:8px;color:var(--muted);border:1px solid var(--line);border-radius:999px;padding:8px 13px;background:#0b1929}.dot{width:8px;height:8px;border-radius:50%;background:var(--green);box-shadow:0 0 10px var(--green)}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.card{background:linear-gradient(145deg,#10233aee,#0b192aec);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);padding:18px;min-width:0}.metric{grid-column:span 3}.wide{grid-column:span 8}.side{grid-column:span 4}.full{grid-column:1/-1}.metric h3{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:0 0 12px}.metric .value{font-size:30px;font-weight:750}.metric .hint{color:var(--muted);font-size:12px;margin-top:7px}.card h2{font-size:15px;margin:0 0 14px;display:flex;justify-content:space-between;align-items:center}.tag{font-size:11px;padding:3px 8px;border-radius:99px;background:#173452;color:var(--cyan);font-weight:600}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:13px}.toolbar input{min-width:180px;flex:1;background:#091727;border:1px solid var(--line);border-radius:8px;padding:9px;color:var(--text);outline:none}.toolbar input:focus{border-color:var(--cyan)}.list{max-height:410px;overflow:auto}.row{display:flex;gap:10px;align-items:flex-start;border-top:1px solid #1b3650;padding:11px 0}.row:first-child{border-top:0;padding-top:0}.row .main{flex:1;min-width:0}.name{font-family:ui-monospace,SFMono-Regular,monospace;color:#bde8ff;font-size:12px;word-break:break-all}.desc{color:var(--muted);font-size:12px;margin-top:3px}.badge{white-space:nowrap;font-size:11px;border-radius:99px;padding:3px 7px}.pass{color:var(--green);background:#143c32}.warn{color:var(--amber);background:#47391d}.fail{color:var(--red);background:#4a2631}.skip{color:var(--purple);background:#332951}.event{font-family:ui-monospace,SFMono-Regular,monospace;font-size:11px}.event .type{color:var(--cyan)}.event .time{color:var(--muted);margin-left:7px}.empty{color:var(--muted);padding:25px 0;text-align:center}.bar{height:8px;border-radius:10px;background:#1b334b;overflow:hidden;margin:8px 0 14px}.bar span{display:block;height:100%;background:linear-gradient(90deg,var(--cyan),var(--green));border-radius:inherit;width:0;transition:width .35s}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.summary div{background:#091727;border:1px solid #1a354d;border-radius:9px;padding:10px}.summary b{display:block;font-size:20px}.summary small{color:var(--muted)}pre{margin:0;white-space:pre-wrap;word-break:break-word;color:#b9cde0;font-size:11px;max-height:220px;overflow:auto}.footer{color:#66829b;font-size:11px;text-align:center;padding:22px}.pulse{animation:pulse 2s infinite}@keyframes pulse{50%{opacity:.55}}@media(max-width:1000px){.metric{grid-column:span 6}.wide,.side{grid-column:1/-1}}@media(max-width:600px){.shell{padding:13px}.top{display:block}.status{margin-top:15px;display:inline-flex}.metric{grid-column:1/-1}.summary{grid-template-columns:repeat(2,1fr)}}
</style></head>
<body><main class="shell">
<header class="top"><div class="brand"><div class="mark">CX</div><div><div class="eyebrow">Cognitive Orchestration · Real-time Tactical Execution</div><div class="title">C.O.R.T.E.X. Operations</div><div class="subtitle">Центральная нервная система распределённых агентов</div></div></div><div class="status"><span class="dot" id="dot"></span><span id="healthText">connecting…</span></div></header>
<section class="grid">
<div class="card metric"><h3>Runtime</h3><div class="value" id="toolsCount">—</div><div class="hint">доступных инструментов</div></div>
<div class="card metric"><h3>Event bus</h3><div class="value" id="eventsCount">—</div><div class="hint">событий в журнале</div></div>
<div class="card metric"><h3>Active tasks</h3><div class="value" id="tasksCount">—</div><div class="hint">workflow executions</div></div>
<div class="card metric"><h3>Toolkit audit</h3><div class="value" id="coverage">—</div><div class="hint">практическое покрытие</div></div>
<div class="card wide"><h2>Инструменты <span class="tag" id="providerTag">agent-toolkit</span></h2><div class="toolbar"><input id="search" placeholder="Найти: SQL, антенна, PDF…"><button onclick="loadTools()">Искать</button><button onclick="runAudit()">Запустить аудит</button></div><div class="list" id="tools"><div class="empty pulse">Загрузка каталога…</div></div></div>
<div class="card side"><h2>Последний аудит <span class="tag" id="auditStatus">нет данных</span></h2><div id="auditSummary" class="empty">Аудит ещё не запускался.</div><div class="bar"><span id="auditBar"></span></div><div id="recommendations"></div></div>
<div class="card wide"><h2>Event stream <span class="tag">live SSE</span></h2><div class="list" id="events"><div class="empty">Ожидание событий шины…</div></div></div>
<div class="card side"><h2>Workflows <button onclick="loadTasks()">↻</button></h2><div class="list" id="tasks"><div class="empty">Нет задач</div></div></div>
<div class="card full"><h2>Blackboard / traces <span class="tag">context-preserving</span></h2><pre id="blackboard">Состояние общей доски загружается…</pre></div>
</section><div class="footer">C.O.R.T.E.X. v0.1.0 · local-first runtime · secrets never rendered in UI</div></main>
<script>
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function get(url){const r=await fetch(url);if(!r.ok)throw Error(await r.text());return r.json()}
function statusBadge(status){let c=status==='passed'?'pass':status.includes('configuration')?'warn':status.includes('skipped')?'skip':status==='failed'?'fail':'warn';return `<span class="badge ${c}">${esc(status)}</span>`}
async function refresh(){try{const h=await get('/health');$('healthText').textContent=`online · ${h.environment||'development'}`;$('toolsCount').textContent=h.tools_count??0;$('eventsCount').textContent=h.events_count??0;$('tasksCount').textContent=h.tasks_count??0;const a=await get('/api/toolkit/audit/latest');if(a&&a.report_id)renderAudit(a);loadTasks();loadTools()}catch(e){$('healthText').textContent='offline';$('dot').style.background='var(--red)'}}
async function loadTools(){try{const q=$('search').value;const data=await get('/api/tools'+(q?'?q='+encodeURIComponent(q):''));$('providerTag').textContent=data.provider||'agent-toolkit';$('tools').innerHTML=(data.tools||[]).slice(0,120).map(t=>`<div class="row"><div class="main"><div class="name">${esc(t.name)}</div><div class="desc">${esc(t.description||'')}</div></div>${t.dangerous?'<span class="badge fail">dangerous</span>':''}</div>`).join('')||'<div class="empty">Ничего не найдено</div>'}catch(e){$('tools').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderAudit(a){$('auditStatus').textContent=a.success?'completed':'failed';$('coverage').textContent=(a.tested||0)+'/'+(a.total||0);$('auditBar').style.width=(a.total?Math.min(100,(a.tested/a.total)*100):0)+'%';$('auditSummary').innerHTML=`<div class="summary"><div><b>${a.passed||0}</b><small>работает</small></div><div><b>${a.requires_configuration||0}</b><small>настройка</small></div><div><b>${a.failed||0}</b><small>ошибки</small></div><div><b>${a.skipped||0}</b><small>policy skip</small></div></div>`;$('recommendations').innerHTML=(a.recommendations||[]).map(r=>`<div class="row"><div class="main"><span class="badge ${r.priority==='high'?'fail':r.priority==='medium'?'warn':'skip'}">${esc(r.priority)}</span> ${esc(r.text)}</div></div>`).join('')}
async function runAudit(){try{const r=await fetch('/api/toolkit/audit',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({run:true})});const d=await r.json();$('auditStatus').textContent='running';if(d.result)renderAudit(d.result);else setTimeout(refresh,350)}catch(e){alert(e.message)}}
async function loadTasks(){try{const d=await get('/api/tasks');$('tasks').innerHTML=(d.tasks||[]).slice(-10).reverse().map(t=>`<div class="row"><div class="main"><div class="name">${esc(t.title)}</div><div class="desc">${esc(t.task_id.slice(0,8))} · ${esc(t.workflow)}</div></div>${statusBadge(t.status)}</div>`).join('')||'<div class="empty">Нет задач</div>'}catch(e){}}
async function loadEvents(){try{const d=await get('/api/events?limit=35');$('events').innerHTML=(d.events||[]).slice().reverse().map(e=>`<div class="row event"><div class="main"><span class="type">${esc(e.event_type)}</span><span class="time">${esc((e.occurred_at||'').slice(11,19))}</span><div class="desc">${esc(e.source)} · ${esc(e.correlation_id||'').slice(0,12)}</div></div></div>`).join('')||'<div class="empty">Нет событий</div>'}catch(e){}}
async function loadBlackboard(){try{$('blackboard').textContent=JSON.stringify(await get('/api/blackboard'),null,2)}catch(e){}}
function connect(){try{const es=new EventSource('/api/stream');es.onmessage=()=>{loadEvents();refresh()};es.onerror=()=>{es.close();setTimeout(connect,4000)}}catch(e){}}
$('search').addEventListener('keydown',e=>{if(e.key==='Enter')loadTools()});refresh();loadEvents();loadBlackboard();connect();setInterval(()=>{loadEvents();loadTasks()},8000);
</script></body></html>'''


__all__ = ["get_ui_html"]
